public int NumDecodings(string s)
{
    if (string.IsNullOrEmpty(s) || s[0] == '0') return 0;
    int prev2 = 1, prev1 = 1;
    for (int i = 1; i < s.Length; i++)
    {
        int curr = 0;
        if (s[i] != '0') curr += prev1;
        int twoDigit = int.Parse(s.Substring(i - 1, 2));
        if (twoDigit >= 10 && twoDigit <= 26) curr += prev2;
        if (curr == 0) return 0;
        prev2 = prev1; prev1 = curr;
    }
    return prev1;
}
